"use strict";
/**
 * Bundler regression — reachability, disk reconciliation, and honest status.
 *
 * `bundle_skill.py` discovers what to copy by walking a skill's own files and
 * following references to a fixed point. The loop itself has been correct since
 * the bundler's first commit. What was wrong is *reachability into it*: a file
 * already sitting in `<skill>/references/` that the walk no longer reaches was
 * never opened, never compared, never refreshed — and the bundler then printed
 * `in sync`.
 *
 * Measured on this repo before the fix: 858 bundled files, 749 regenerated by a
 * clean run, 109 never regenerated. Of those, 26 had a `shared/resources/`
 * source and 8 were provably stale — including two copies of a pipeline contract
 * carrying `"current_step": 1`, the exact value the shared source's own warning
 * block exists to forbid. Zero of the 749 discovered files were stale, so the
 * bundler was correct on everything it examined and silent about everything else.
 *
 * Two causes, and one tempting fix that had to be rejected:
 *   1. `.json` was absent from REFS_REF_RE's suffix alternation, so a skill whose
 *      only reference was `references/x.json` computed |needed| == 0, took the
 *      early return, and never touched its references/ dir at all.
 *   2. Most of them are reachable by no rule at all — something placed the copy and
 *      nothing points at it any more. Pass 2 therefore reconciles against DISK: a
 *      copy is refreshed because it exists and has a source, not because discovery
 *      found it.
 *
 * REJECTED: following `references/X` out of shared text. It looks like the obvious
 * fix and it over-vendors — `tracker-card-summary.md` names `references/jira-sync.js`
 * while explicitly avoiding the `shared/resources/` form so the bundler will NOT
 * vendor a Jira client into GitHub-only skills. Trying it added 38 unwanted files.
 * A prose mention is not a dependency; the guard test below pins that.
 *
 * The boundary that matters: a `references/` file WITH a `shared/resources/`
 * source is a stale copy and gets refreshed; one WITHOUT a source is a
 * skill-native file and must be left alone. 83 of the 109 are the latter.
 *
 * Each test builds a throwaway repo and runs the real bundler, so the assertions
 * are about observed behaviour rather than a re-implementation of its regexes.
 *
 * Run: node --test tests/bundle-transitive.test.js
 */

const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync } = require("child_process");
const test = require("node:test");
const assert = require("node:assert/strict");

const REPO_ROOT = path.resolve(__dirname, "..");
const BUNDLER = path.join(
  REPO_ROOT,
  "skills",
  "create-skill",
  "scripts",
  "bundle_skill.py",
);

const SKILL_MD_HEAD = `---
name: fixture-skill
description: Fixture skill used by the bundler reachability regression test.
---

# Fixture Skill
`;

/**
 * Build a disposable repo with one skill plus a shared/resources tree.
 *
 * Unlike the helper in bundle-mjs.test.js this does NOT run the bundler eagerly —
 * these tests need to bundle, mutate a source, and bundle again, which is the
 * only way to observe a refresh (as opposed to an initial copy).
 *
 * A real temp repo keeps the test from mutating tracked files: the bundler
 * rewrites sources in place by design.
 */
function makeFixture({ skillFiles = {}, sharedFiles = {}, refsFiles = {} }) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "bundle-transitive-"));
  // find_repo_root() walks up looking for these markers.
  fs.mkdirSync(path.join(root, "skills"), { recursive: true });
  fs.mkdirSync(path.join(root, "shared", "resources"), { recursive: true });
  fs.writeFileSync(path.join(root, "package.json"), '{"name":"fixture"}\n');

  const skillDir = path.join(root, "skills", "fixture-skill");
  fs.mkdirSync(skillDir, { recursive: true });

  const writeAll = (base, files) => {
    for (const [rel, content] of Object.entries(files)) {
      const dest = path.join(base, rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, content);
    }
  };

  writeAll(skillDir, skillFiles);
  writeAll(path.join(root, "shared", "resources"), sharedFiles);
  // Pre-existing bundled copies — the state a real checkout is in.
  writeAll(path.join(skillDir, "references"), refsFiles);

  const bundle = () =>
    execFileSync("python3", [BUNDLER, skillDir], { encoding: "utf-8" });

  return {
    root,
    skillDir,
    bundle,
    writeShared: (name, content) =>
      fs.writeFileSync(path.join(root, "shared", "resources", name), content),
    readRef: (name) =>
      fs.readFileSync(path.join(skillDir, "references", name), "utf-8"),
    refExists: (name) => fs.existsSync(path.join(skillDir, "references", name)),
    check: () => {
      // `--check` must not write. Returns {status, stdout} rather than throwing,
      // because a non-zero exit is the expected result in half these tests.
      try {
        return {
          status: 0,
          stdout: execFileSync("python3", [BUNDLER, "--check", skillDir], {
            encoding: "utf-8",
          }),
        };
      } catch (e) {
        return {
          status: e.status,
          stdout: (e.stdout || "") + (e.stderr || ""),
        };
      }
    },
  };
}

test("a copy reachable by no discovery rule is REFRESHED when its source changes", () => {
  // The real shape of the defect. All 26 affected files in this repo were already
  // sitting in references/ — put there by an earlier bundle or a hand-sync — and
  // nothing the walk can see points at them any more. Discovery cannot be widened
  // to reach them (see the over-vendoring guard below), so reconciliation keys on
  // the copy existing and having a source.
  const fx = makeFixture({
    skillFiles: {
      "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
    },
    sharedFiles: { "contract.md": "# Contract\n\nORIGINAL body.\n" },
    refsFiles: { "contract.md": "# Contract\n\nORIGINAL body.\n" },
  });

  fx.bundle();
  fx.writeShared("contract.md", "# Contract\n\nCORRECTED body.\n");
  const stdout = fx.bundle();

  assert.match(
    fx.readRef("contract.md"),
    /CORRECTED body/,
    "This is the defect in full: the source moved on and the bundled copy did not, " +
      "so the copy describes an earlier version forever while the bundler reports " +
      `success. Bundler said:\n${stdout}`,
  );
});

test("`in sync` is not printed when a source-backed copy was actually refreshed", () => {
  const fx = makeFixture({
    skillFiles: {
      "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
    },
    sharedFiles: { "contract.md": "# Contract\n\nCURRENT body.\n" },
    refsFiles: { "contract.md": "# Contract\n\nSTALE body.\n" },
  });

  const stdout = fx.bundle();

  assert.doesNotMatch(
    stdout,
    /in sync/,
    `A run that rewrote a stale file must not report it as already correct. Said:\n${stdout}`,
  );
  assert.match(
    stdout,
    /reconciled/,
    `The refresh should be reported so the operator can see it happened. Said:\n${stdout}`,
  );
});

test("a `references/X` mention inside shared PROSE does not vendor the file", () => {
  // Regression guard for an over-correction found while implementing this task.
  // Following `references/X` out of shared text looks like the obvious fix for
  // unreachable copies, and it is wrong: `shared/resources/tracker-card-summary.md`
  // names `references/jira-sync.js` while stating outright that it avoids the
  // `shared/resources/` form so the bundler will NOT vendor a Jira client into
  // GitHub-only skills. Making prose a dependency edge added 38 unwanted files
  // across this repo. Only files a skill actually reaches, or already holds, belong
  // in its references/.
  const fx = makeFixture({
    skillFiles: {
      "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/spec.md.\n`,
    },
    sharedFiles: {
      "spec.md":
        "# Spec\n\nHelpers live in the shared library (vendored as " +
        "`references/heavy-client.js` in skills that need it). Its path is " +
        "deliberately not spelled out.\n",
      "heavy-client.js": "module.exports = {};\n",
    },
  });

  fx.bundle();

  assert.equal(
    fx.refExists("heavy-client.js"),
    false,
    "A prose mention is not a dependency. Vendoring on the strength of one puts a " +
      "Jira client into every GitHub-only skill that merely documents the contract.",
  );
});

test("`references/x.json` is discovered — .json must be in the suffix alternation", () => {
  const fx = makeFixture({
    skillFiles: {
      "SKILL.md": `${SKILL_MD_HEAD}\nThe graph lives in \`references/graph.json\`.\n`,
    },
    sharedFiles: {
      "graph.json": '{\n  "fixture-skill": []\n}\n',
    },
  });

  const stdout = fx.bundle();

  assert.ok(
    fx.refExists("graph.json"),
    "A skill whose only reference is `references/graph.json` must still bundle " +
      "it. Without `json` in the suffix alternation the skill computes " +
      "|needed| == 0, takes the early return, and never touches references/ at " +
      `all. Bundler said:\n${stdout}`,
  );
});

test("a stale copy WITH a shared source is reconciled even when discovery cannot reach it", () => {
  const fx = makeFixture({
    skillFiles: {
      // SKILL.md references nothing at all — orphan.md is unreachable by any rule.
      "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
    },
    sharedFiles: {
      "orphan.md": "# Orphan\n\nCURRENT source body.\n",
    },
    refsFiles: {
      "orphan.md": "# Orphan\n\nANCIENT stale body.\n",
    },
  });

  const stdout = fx.bundle();

  assert.match(
    fx.readRef("orphan.md"),
    /CURRENT source body/,
    "A file sitting in references/ that has a shared/resources/ counterpart is a " +
      "stale copy, whatever discovery thinks. Pass 2 must reconcile against disk, " +
      `not only against the discovered set. Bundler said:\n${stdout}`,
  );
});

test("a copy WITHOUT a shared source is left untouched — the out-of-scope boundary", () => {
  const NATIVE =
    "# Skill-native\n\nThis file has no shared/resources source.\n";
  const fx = makeFixture({
    skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing shared.\n` },
    sharedFiles: {},
    refsFiles: { "skill-native.md": NATIVE },
  });

  fx.bundle();

  assert.equal(
    fx.readRef("skill-native.md"),
    NATIVE,
    "83 of this repo's 109 non-regenerated bundled files are skill-native and " +
      "legitimately live in references/. Reconciliation must key on HAVING a " +
      "source, never on mere presence, or it deletes or clobbers them.",
  );
});

test("the bundler stays idempotent — a second run reports no changes", () => {
  const fx = makeFixture({
    skillFiles: {
      "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/outer.md.\n`,
    },
    sharedFiles: {
      "outer.md": "# Outer\n\nRun `references/inner.md`.\n",
      "inner.md": "# Inner\n\nBody.\n",
    },
  });

  fx.bundle();
  const second = fx.bundle();

  assert.match(
    second,
    /in sync/,
    "Idempotence is a load-bearing contract (AGENTS.md, the module docstring, and " +
      "the validate.yml freshness step all depend on it). A second run must be a " +
      `no-op. Bundler said:\n${second}`,
  );
});

test("--check fails on a staled copy that discovery cannot reach", () => {
  const fx = makeFixture({
    skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing shared.\n` },
    sharedFiles: { "orphan.md": "# Orphan\n\nCURRENT source body.\n" },
    refsFiles: { "orphan.md": "# Orphan\n\nANCIENT stale body.\n" },
  });

  const res = fx.check();

  assert.equal(
    res.status,
    1,
    "This is the case the existing regenerate-and-git-diff CI check is " +
      "structurally blind to: the bundler never writes the file, so git sees no " +
      "diff and the lane stays green while the copy is stale. --check must " +
      `compare per-file instead. Output:\n${res.stdout}`,
  );
  assert.match(
    res.stdout,
    /orphan\.md/,
    "The failure must name the offending file so the operator can act on it.",
  );
});

test("--check passes on a correctly bundled tree, and writes nothing", () => {
  const fx = makeFixture({
    skillFiles: {
      "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/outer.md.\n`,
    },
    sharedFiles: { "outer.md": "# Outer\n\nBody.\n" },
  });

  fx.bundle();
  const before = fx.readRef("outer.md");
  const res = fx.check();

  assert.equal(
    res.status,
    0,
    `--check should pass here. Output:\n${res.stdout}`,
  );
  assert.equal(
    fx.readRef("outer.md"),
    before,
    "--check must be read-only — CI runs it to detect drift, not to repair it.",
  );
});
